```python
dirs = ['north', 'east', 'south', 'west']  # clockwise: right = +1, left = -1, around = +2
move = {'north': (0, 1), 'east': (1, 0), 'south': (0, -1), 'west': (-1, 0)}
x, y, d = 0, 0, 0
steps = [('forward', 3), ('forward', 4), ('forward', 2), ('forward', 4), ('forward', 2), ('right', 0), ('forward', 1), ('forward', 2), ('left', 0), ('right', 0)]
for act, n in steps:
    if act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
    elif act == 'right':
        d = (d + 1) % 4
    elif act == 'left':
        d = (d - 1) % 4
    elif act == 'around':
        d = (d + 2) % 4
print((x, y))
```

