x, y, d = 0, 0, 0
steps = [('forward', 3), ('left', 0), ('left', 1), ('forward', 4), ('forward', 4), ('left', 1), ('forward', 2), ('forward', 2), ('forward', 2), ('forward', 4)]
for act, n in steps:
    if act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
    elif act == 'left':
        d = (d - 1) % 4
    elif act == 'right':
        d = (d + 1) % 4
    elif act == 'around':
        d = (d + 2) % 4
print((x, y))
