x, y, d = 0, 0, 0
steps = [('right', 0), ('right', 0), ('left', 0), ('forward', 3), ('forward', 1), ('forward', 1), ('forward', 1), ('forward', 2), ('forward', 4), ('forward', 3)]
for act, n in steps:
    if act == 'right':
        d = (d + 1) % 4
    elif act == 'left':
        d = (d - 1) % 4
    elif act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
print((x, y))
```

