x, y, d = 0, 0, 0
steps = [('turn right', 0), ('turn right', 0), ('forward', 2), ('forward', 2), ('forward', 1), ('turn right', 0), ('turn left', 0), ('turn right', 0), ('forward', 2), ('turn left', 0)]
for act, n in steps:
    if act == 'forward':
        dx, dy = move[dirs[d]]
        x, y = x + dx * n, y + dy * n
    elif act == 'turn right':
        d = (d + 1) % 4
    elif act == 'turn left':
        d = (d - 1) % 4
    elif act == 'turn around':
        d = (d + 2) % 4
print((x, y))
```

